<script setup lang="ts">
import { computed, ref } from 'vue';
import { Plus, Settings2, Trash2 } from 'lucide-vue-next';
import { request, infraNames, moduleProducts } from './model';
import type { State, Module, Infra } from './model';
const props=defineProps<{state:State;module:Module;initialInfra?:Infra}>();
const emit=defineEmits<{saved:[state:State];busy:[value:boolean];deleted:[]}>();
const rackSide=ref('L'),rackName=ref(''),deleteID=ref(''),deleteWhole=ref(false);
const racks=computed(()=>props.state.racks.filter(r=>r.moduleId===props.module.id).sort((a,b)=>a.side.localeCompare(b.side)||a.index-b.index));
const moduleDevices=computed(()=>props.state.devices.filter(d=>d.moduleId===props.module.id));
const metadata=ref({...props.module});const error=ref(''),message=ref(''),working=ref(false);
const fresh=():Infra=>({id:'',name:'',kind:'ac',moduleId:props.module.id,side:'L',afterRack:0,placement:'inline'});
const form=ref<Infra>(props.initialInfra?{...props.initialInfra}:fresh());
const slots=computed(()=>props.state.infra.filter(i=>i.moduleId===props.module.id));
const count=computed(()=>form.value.side==='L'?props.module.rackLeft:props.module.rackRight);
const positions=computed(()=>Array.from({length:count.value+(form.value.placement==='inline'?1:0)},(_,i)=>i+(form.value.placement==='inline'?0:1)));
async function save(path:string,method:string,body:object){working.value=true;emit('busy',true);error.value='';message.value='';try{const next=await request<State>(path,method,{revision:props.state.revision,...body});emit('saved',next);message.value='布局已保存';return true}catch(e){error.value=(e as Error).message;if((e as {status?:number}).status===409){try{emit('saved',await request<State>('/state'))}catch{}}return false}finally{working.value=false;emit('busy',false)}}
async function saveMetadata(){await save('/modules/'+props.module.id,'PUT',metadata.value)}
async function saveSlot(){const item={...form.value};if(!item.name)item.name=infraNames[item.kind]+' · 位置待确认';if(await save('/infrastructure'+(item.id?'/'+item.id:''),item.id?'PUT':'POST',{infra:item})){form.value=fresh()}}
async function removeSlot(){if(form.value.id&&await save('/infrastructure/'+form.value.id,'DELETE',{}))form.value=fresh()}
async function addRack(){if(await save('/modules/'+props.module.id+'/racks','POST',{side:rackSide.value,name:rackName.value}))rackName.value=''}
async function deleteRack(){if(deleteID.value&&await save('/racks/'+deleteID.value,'DELETE',{}))deleteID.value=''}
async function deleteModule(){if(await save('/modules/'+props.module.id,'DELETE',{}))emit('deleted')}
function normalize(){if(!positions.value.includes(form.value.afterRack))form.value.afterRack=positions.value[0]||0}
</script>
<template>
 <div class="layout-editor"><div v-if="error" class="error-banner" role="alert">{{error}}</div><p v-if="message" class="info-banner" role="status">{{message}}</p>
 <form @submit.prevent="saveMetadata"><div class="form-grid"><label>微模块名称<input v-model="metadata.name" required maxlength="80"/></label><label>点位标识<input v-model="metadata.point" maxlength="80" placeholder="例如：点位1"/></label><label>所属机房<select v-model="metadata.siteId" aria-label="微模块所属机房"><optgroup v-for="p in state.projects" :key="p.id" :label="p.name"><option v-for="room in state.sites.filter(s=>s.projectId===p.id)" :key="room.id" :value="room.id">{{room.name}}</option></optgroup></select></label><label>微模块型号<input v-model="metadata.productModel" list="layout-products" maxlength="120"/><datalist id="layout-products"><option v-for="p in moduleProducts" :key="p" :value="p"/></datalist></label></div><div class="layout-save"><span class="muted small">{{module.type==='double'?'双排冷通道':'单排'}} · {{module.rackLeft+module.rackRight}} 个设备柜</span><button class="primary" :disabled="working"><Settings2 :size="14"/>保存模块信息</button></div></form>
 <section class="rack-management"><div class="form-section-heading"><h3>机柜管理 · {{racks.length}}柜</h3></div><form class="quick-filters" @submit.prevent="addRack"><select v-model="rackSide" aria-label="新增机柜所属列"><option value="L">L列</option><option v-if="module.type==='double'" value="R">R列</option></select><input v-model="rackName" aria-label="新增机柜名称" maxlength="80" placeholder="机柜名称（留空自动编号）"/><button class="primary" :disabled="working">新增机柜</button></form><div class="rack-management-list"><div v-for="rack in racks" :key="rack.id"><strong>{{rack.name}}</strong><span>{{rack.side}}列第{{rack.index}}位 · {{state.devices.filter(d=>d.rackId===rack.id).length}}台设备</span><button class="text-button danger-text" :aria-label="'删除机柜 '+rack.name" :disabled="working" @click="deleteID=rack.id;deleteWhole=false">删除</button></div></div><div v-if="deleteID" class="delete-inline" role="region" aria-label="确认删除机柜"><p>删除「{{racks.find(r=>r.id===deleteID)?.name}}」？有设备或柜内设施时请先迁移。其余机柜和独立设施顺序保留。</p><button class="secondary" @click="deleteID=''">取消删除</button><button class="danger" :disabled="working" @click="deleteRack">确认删除机柜</button></div></section>
 <div class="form-section-heading"><h3>按列配置基础设施</h3><button class="text-button" :disabled="working" @click="form=fresh()"><Plus :size="14"/>新增设施</button></div><details class="compact-help"><summary>操作帮助</summary><p>“列内独立”占用柜列中的独立位置；“柜内集成”归属所选机柜。此处描述空间归属，不自动占用 U 位；确认占 U 的设备需同时录入设备台账。</p></details>
 <div class="infra-slot-list"><button v-for="item in slots" :key="item.id" :disabled="working" :class="{active:form.id===item.id}" @click="form={...item}"><span>{{item.name}}</span><small>{{item.side}}列 · {{item.placement==='integrated'?`柜${item.afterRack}内集成`:item.afterRack?`柜${item.afterRack}后`:'列首'}}</small></button></div>
 <form class="infra-form" @submit.prevent="saveSlot"><div class="form-grid"><label>设施名称<input v-model="form.name" maxlength="80" placeholder="例如：L列列间空调01"/></label><label>设施类别<select v-model="form.kind" aria-label="设施类别"><option v-for="(name,kind) in infraNames" :key="kind" :value="kind">{{name}}</option></select></label><label>所属列<select v-model="form.side" aria-label="设施所属列" @change="normalize"><option value="L">L列{{module.type==='single'?'（单排）':''}}</option><option v-if="module.type==='double'" value="R">R列</option></select></label><label>安装方式<select v-model="form.placement" aria-label="设施安装方式" @change="normalize"><option value="inline">列内独立设施</option><option value="integrated">柜内集成设施</option></select></label><label>列内位置<select v-model.number="form.afterRack" aria-label="设施列内位置"><option v-for="position in positions" :key="position" :value="position">{{form.placement==='integrated'?`${form.side}${String(position).padStart(2,'0')} 柜内`:position===0?'列首（第一个机柜前）':`${form.side}${String(position).padStart(2,'0')} 机柜之后`}}</option></select></label></div><div class="layout-save"><button v-if="form.id" type="button" class="text-button danger-text" :disabled="working" @click="removeSlot"><Trash2 :size="14"/>删除此设施</button><span v-else class="muted small">按现场布置设置，可重复添加空调/供电等设施</span><button class="primary" :disabled="working">{{form.id?'保存设施位置':'新增基础设施'}}</button></div></form>
 <details class="compact-help module-delete-settings"><summary>删除微模块</summary><p>删除微模块及其 {{racks.length}} 个机柜、{{slots.length}} 项设施。机房和其他模块保留；当前模块有 {{moduleDevices.length}} 台设备（含待上架），须先迁移设备才能删除。</p><button v-if="!deleteWhole" class="text-button danger-text" :disabled="working" @click="deleteWhole=true;deleteID=''">删除此微模块</button><div v-else class="delete-inline"><button class="secondary" @click="deleteWhole=false">取消删除</button><button class="danger" :disabled="working" @click="deleteModule">确认删除微模块</button></div></details>
 </div>
</template>
